// ─── File: DeliveryDemo.java ───
package com.bank.delivery;

import java.util.logging.*;

public class DeliveryDemo {
    private static final Logger log = Logger.getLogger("Delivery");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // PULL: short polling — mostly "no change"
        PollingClient poll = new PollingClient();
        for (int i = 1; i <= 3; i++) {
            String r = poll.pollOnce("transfer-1");
            int n = i;
            log.info(() -> "poll #" + n + " -> " + r);
        }
        poll.serverMarkComplete("transfer-1");
        log.info(() -> "poll #4 -> " + poll.pollOnce("transfer-1"));

        // PULL improved: long polling — returns as soon as an update exists
        LongPollServer lp = new LongPollServer();
        lp.update("transfer-2", "COMPLETED");
        log.info(() -> "long-poll -> " + lp.waitForUpdate("transfer-2"));

        // PUSH: SSE — server pushes to a connected client
        SsePushServer sse = new SsePushServer();
        sse.connect("SAV2001", msg -> log.info(() -> "  SSE to SAV2001: " + msg));
        sse.pushTransaction("SAV2001", "Rs.50000 to CUR3001");

        // PUSH: mobile notification — reaches an OFFLINE device
        PushNotificationService push = new PushNotificationService();
        push.send("CUR3001-device", "Fraud alert: verify recent activity");
    }
}

