// ─── File: PollingClient.java ───
package com.bank.delivery;

import java.util.*;

// Short polling: client repeatedly asks; server usually has no change.
public class PollingClient {
    private final Map<String,String> serverState = new HashMap<>();
    public void serverMarkComplete(String id) { serverState.put(id, "COMPLETED"); }
    public String pollOnce(String id) {
        return serverState.getOrDefault(id, "NO_CHANGE");   // wasted when NO_CHANGE
    }
}
```

