// ─── File: LongPollServer.java ───
package com.bank.delivery;

import java.util.*;

// Long polling: the server holds the request until an update exists (or timeout).
public class LongPollServer {
    private final Map<String,String> updates = new HashMap<>();
    public void update(String id, String status) { updates.put(id, status); }
    public String waitForUpdate(String id) {
        // simulate holding open until data is available
        long deadline = System.currentTimeMillis() + 1000;
        while (System.currentTimeMillis() < deadline) {
            if (updates.containsKey(id)) return updates.get(id);  // return as soon as ready
            try { Thread.sleep(10); } catch (InterruptedException ignored) {}
        }
        return "TIMEOUT";   // client reconnects
    }
}
```

