// ─── File: SsePushServer.java ───
package com.bank.delivery;

import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

// Server-Sent Events: one-way server push over a long-lived connection.
public class SsePushServer {
    private static final Logger log = Logger.getLogger("Delivery");
    private final Map<String, Consumer<String>> connections = new HashMap<>();
    public void connect(String clientId, Consumer<String> emitter) {
        connections.put(clientId, emitter);   // presence registry
        log.fine(() -> clientId + " connected (SSE)");
    }
    public void pushTransaction(String clientId, String event) {
        Consumer<String> emitter = connections.get(clientId);
        if (emitter != null) emitter.accept(event);   // server initiates delivery
        else log.warning(() -> clientId + " not connected");
    }
}
```

